// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seedA, uint256 seedB) public {
        vm.assume(seedA != seedB);
        vm.deal(address(this), 100 ether);

        // Set block.timestamp so first call succeeds
        vm.warp(block.timestamp + 1);

        // First call
        (bool success1,) = address(c).call{value: 10 ether}("");
        vm.assume(success1);

        // Try again in same block (will revert in P due to timestamp check, but not in M)
        (bool success2,) = address(c).call{value: 10 ether}("");

        // Rule: second call must revert because block.timestamp == pastBlockTime
        assertTrue(!success2);
    }
}

